4303                                 FPClassTest InterestedClasses, unsigned Depth,
4304                                 const SimplifyQuery &Q) {
4305   auto *FVTy = dyn_cast<FixedVectorType>(V->getType());
4306   APInt DemandedElts =
4307       FVTy ? APInt::getAllOnes(FVTy->getNumElements()) : APInt(1, 1);
