4311 static void computeKnownFPClassForFPTrunc(const Operator *Op,
4312                                           const APInt &DemandedElts,
4313                                           FPClassTest InterestedClasses,
4314                                           KnownFPClass &Known, unsigned Depth,
4315                                           const SimplifyQuery &Q) {
4316   if ((InterestedClasses &
4317        (KnownFPClass::OrderedLessThanZeroMask | fcNan)) == fcNone)
4318     return;
4319 
4320   KnownFPClass KnownSrc;
4321   computeKnownFPClass(Op->getOperand(0), DemandedElts, InterestedClasses,
4322                       KnownSrc, Depth + 1, Q);
4323 
4324   // Sign should be preserved
4325   // TODO: Handle cannot be ordered greater than zero
4326   if (KnownSrc.cannotBeOrderedLessThanZero())
4327     Known.knownNot(KnownFPClass::OrderedLessThanZeroMask);
4328 
4329   Known.propagateNaN(KnownSrc, true);
4330 
4331   // Infinity needs a range check.
4332 }
