4334 void computeKnownFPClass(const Value *V, const APInt &DemandedElts,
4335                          FPClassTest InterestedClasses, KnownFPClass &Known,
4336                          unsigned Depth, const SimplifyQuery &Q) {
4337   assert(Known.isUnknown() && "should not be called with known information");
4338 
4339   if (!DemandedElts) {
4340     // No demanded elts, better to assume we don't know anything.
4341     Known.resetAll();
4342     return;
4343   }
4344 
4345   assert(Depth <= MaxAnalysisRecursionDepth && "Limit Search Depth");
4346 
4347   if (auto *CFP = dyn_cast_or_null<ConstantFP>(V)) {
4348     Known.KnownFPClasses = CFP->getValueAPF().classify();
4349     Known.SignBit = CFP->isNegative();
4350     return;
4351   }
4352 
4353   // Try to handle fixed width vector constants
4354   auto *VFVTy = dyn_cast<FixedVectorType>(V->getType());
4355   const Constant *CV = dyn_cast<Constant>(V);
4356   if (VFVTy && CV) {
4357     Known.KnownFPClasses = fcNone;
4358     bool SignBitAllZero = true;
4359     bool SignBitAllOne = true;
4360 
4361     // For vectors, verify that each element is not NaN.
4362     unsigned NumElts = VFVTy->getNumElements();
4363     for (unsigned i = 0; i != NumElts; ++i) {
4364       Constant *Elt = CV->getAggregateElement(i);
4365       if (!Elt) {
4366         Known = KnownFPClass();
4367         return;
4368       }
4369       if (isa<UndefValue>(Elt))
4370         continue;
4371       auto *CElt = dyn_cast<ConstantFP>(Elt);
4372       if (!CElt) {
4373         Known = KnownFPClass();
4374         return;
4375       }
4376 
4377       const APFloat &C = CElt->getValueAPF();
4378       Known.KnownFPClasses |= C.classify();
4379       if (C.isNegative())
4380         SignBitAllZero = false;
4381       else
4382         SignBitAllOne = false;
4383     }
4384     if (SignBitAllOne != SignBitAllZero)
4385       Known.SignBit = SignBitAllOne;
4386     return;
4387   }
4388 
4389   FPClassTest KnownNotFromFlags = fcNone;
4390   if (const auto *CB = dyn_cast<CallBase>(V))
4391     KnownNotFromFlags |= CB->getRetNoFPClass();
4392   else if (const auto *Arg = dyn_cast<Argument>(V))
4393     KnownNotFromFlags |= Arg->getNoFPClass();
4394 
4395   const Operator *Op = dyn_cast<Operator>(V);
4396   if (const FPMathOperator *FPOp = dyn_cast_or_null<FPMathOperator>(Op)) {
4397     if (FPOp->hasNoNaNs())
4398       KnownNotFromFlags |= fcNan;
4399     if (FPOp->hasNoInfs())
4400       KnownNotFromFlags |= fcInf;
4401   }
4402 
4403   KnownFPClass AssumedClasses = computeKnownFPClassFromContext(V, Q);
4404   KnownNotFromFlags |= ~AssumedClasses.KnownFPClasses;
4405 
4406   // We no longer need to find out about these bits from inputs if we can
4407   // assume this from flags/attributes.
4408   InterestedClasses &= ~KnownNotFromFlags;
4409 
4410   auto ClearClassesFromFlags = make_scope_exit([=, &Known] {
4411     Known.knownNot(KnownNotFromFlags);
4412     if (!Known.SignBit && AssumedClasses.SignBit) {
4413       if (*AssumedClasses.SignBit)
4414         Known.signBitMustBeOne();
4415       else
4416         Known.signBitMustBeZero();
4417     }
4418   });
4419 
4420   if (!Op)
4421     return;
4422 
4423   // All recursive calls that increase depth must come after this.
4424   if (Depth == MaxAnalysisRecursionDepth)
4425     return;
4426 
4427   const unsigned Opc = Op->getOpcode();
4428   switch (Opc) {
4429   case Instruction::FNeg: {
4430     computeKnownFPClass(Op->getOperand(0), DemandedElts, InterestedClasses,
4431                         Known, Depth + 1, Q);
4432     Known.fneg();
4433     break;
4434   }
4435   case Instruction::Select: {
