4249 static KnownFPClass computeKnownFPClassFromContext(const Value *V,
4250                                                    const SimplifyQuery &Q) {
4251   KnownFPClass KnownFromContext;
4252 
4253   if (!Q.CxtI)
4254     return KnownFromContext;
4255 
4256   if (Q.DC && Q.DT) {
4257     // Handle dominating conditions.
4258     for (BranchInst *BI : Q.DC->conditionsFor(V)) {
4259       Value *Cond = BI->getCondition();
4260 
4261       BasicBlockEdge Edge0(BI->getParent(), BI->getSuccessor(0));
4262       if (Q.DT->dominates(Edge0, Q.CxtI->getParent()))
4263         computeKnownFPClassFromCond(V, Cond, /*CondIsTrue=*/true, Q.CxtI,
4264                                     KnownFromContext);
4265 
4266       BasicBlockEdge Edge1(BI->getParent(), BI->getSuccessor(1));
4267       if (Q.DT->dominates(Edge1, Q.CxtI->getParent()))
4268         computeKnownFPClassFromCond(V, Cond, /*CondIsTrue=*/false, Q.CxtI,
4269                                     KnownFromContext);
4270     }
4271   }
4272 
4273   if (!Q.AC)
4274     return KnownFromContext;
4275 
4276   // Try to restrict the floating-point classes based on information from
4277   // assumptions.
4278   for (auto &AssumeVH : Q.AC->assumptionsFor(V)) {
4279     if (!AssumeVH)
4280       continue;
4281     CallInst *I = cast<CallInst>(AssumeVH);
4282 
4283     assert(I->getFunction() == Q.CxtI->getParent()->getParent() &&
4284            "Got assumption for the wrong function!");
4285     assert(I->getCalledFunction()->getIntrinsicID() == Intrinsic::assume &&
4286            "must be an assume intrinsic");
4287 
4288     if (!isValidAssumeForContext(I, Q.CxtI, Q.DT))
4289       continue;
4290 
4291     computeKnownFPClassFromCond(V, I->getArgOperand(0), /*CondIsTrue=*/true,
4292                                 Q.CxtI, KnownFromContext);
4293   }
4294 
4295   return KnownFromContext;
4296 }
